import{z}from"zod";const schema=z.object({NEXT_PUBLIC_APP_URL:z.string().url(),NEXT_PUBLIC_SUPABASE_URL:z.string().url(),NEXT_PUBLIC_SUPABASE_ANON_KEY:z.string().min(20)});export function publicEnv(){const parsed=schema.safeParse({NEXT_PUBLIC_APP_URL:process.env.NEXT_PUBLIC_APP_URL,NEXT_PUBLIC_SUPABASE_URL:process.env.NEXT_PUBLIC_SUPABASE_URL,NEXT_PUBLIC_SUPABASE_ANON_KEY:process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY});if(!parsed.success)throw new Error("PUBLIC_ENV_CONFIGURATION_INVALID");return parsed.data}